iterations.rule_text:
{
 "title": "Potential AdFind Execution",
 "description": "Detects execution of adfind.exe with suspicious command-line arguments commonly used for Active Directory reconnaissance.",
 "tags": [
  "attack.discovery",
  "attack.t1087"
 ],
 "logsource_category": "process_creation",
 "groups": [
  {
   "name": "base_image",
   "fields": [
    {
     "field": "Image",
     "modifier": "contains",
     "values": [
      "adfind.exe"
     ]
    }
   ]
  },
  {
   "name": "cmd_showdel",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "-showdel"
     ]
    }
   ]
  },
  {
   "name": "cmd_sdna_nosacl",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "-sdna",
      "-nosacl"
     ]
    }
   ]
  },
  {
   "name": "cmd_security_desc",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "-sddl",
      "-sddc",
      "-owner*"
     ]
    }
   ]
  },
  {
   "name": "cmd_computed_attrs",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "parentrdn",
      "objrdn"
     ]
    }
   ]
  },
  {
   "name": "cmd_default_attrs",
   "fields": [
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "-default"
     ]
    },
    {
     "field": "CommandLine",
     "modifier": "contains",
     "values": [
      "lockoutduration",
      "lockoutthreshold",
      "lockoutobservationwindow",
      "maxpwdage",
      "minpwdage",
      "minpwdlength",
      "pwdhistorylength",
      "pwdproperties"
     ]
    }
   ]
  }
 ],
 "condition": "base_image and (cmd_showdel or cmd_sdna_nosacl or cmd_security_desc or cmd_computed_attrs or cmd_default_attrs)",
 "falsepositives": [
  "Legitimate administrators using AdFind for authorized Active Directory queries."
 ],
 "level": "high"
}

